#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <cstdio>
#include <climits>
using namespace std;

typedef long long ll;
const int MAX_N = 5005;
const int MAX_M = 5050;
const ll INF = 1000000007LL;

inline int inputInt() {
    int x = 0, sign = 0;
    char c = getchar();
    while (c < '0' || c > '9') { if (c == '-') sign = 1; c = getchar(); }
    while (c >= '0' && c <= '9') { x = x * 10 + c - '0'; c = getchar(); }
    return sign ? -x : x;
}

struct PathEdge {
    int src, dest, cap, flow, cost;
    PathEdge(int s, int d, int cp, int fl, int cs)
        : src(s), dest(d), cap(cp), flow(fl), cost(cs) {}
};

int N, M, K, C, D_val;
int A[MAX_M];
int sourceNode, targetNode;

struct MinCostMaxFlow {
    int vertices;
    vector<PathEdge> edgeList;
    vector<int> adjList[MAX_N * 100];
    bool visited[MAX_N * 100];
    int minDist[MAX_N * 100];
    int prevEdgeIdx[MAX_N * 100];
    int pathBottleneck[MAX_N * 100];

    void reset(int v) {
        vertices = v;
        for (int i = 0; i <= v; ++i) {
            adjList[i].clear();
        }
        edgeList.clear();
    }

    void connect(int u, int v, int capacity, int weight) {
        edgeList.emplace_back(u, v, capacity, 0, weight);
        edgeList.emplace_back(v, u, 0, 0, -weight);
        int idx = edgeList.size();
        adjList[u].push_back(idx - 2);
        adjList[v].push_back(idx - 1);
    }

    bool findPath(int s, int t, int &flow, int &totalCost) {
        fill(minDist, minDist + t + 1, INT_MAX);
        fill(visited, visited + t + 1, false);
        fill(pathBottleneck, pathBottleneck + t + 1, 0);
        queue<int> q;

        minDist[s] = 0;
        pathBottleneck[s] = INT_MAX;
        q.push(s);

        while (!q.empty()) {
            int u = q.front(); q.pop();
            visited[u] = false;

            for (int idx : adjList[u]) {
                PathEdge& e = edgeList[idx];
                if (e.cap > e.flow && minDist[e.dest] > minDist[u] + e.cost) {
                    minDist[e.dest] = minDist[u] + e.cost;
                    prevEdgeIdx[e.dest] = idx;
                    pathBottleneck[e.dest] = min(pathBottleneck[u], e.cap - e.flow);
                    if (!visited[e.dest]) {
                        visited[e.dest] = true;
                        q.push(e.dest);
                    }
                }
            }
        }

        if (minDist[t] == INT_MAX) return false;
        flow += pathBottleneck[t];
        totalCost += minDist[t] * pathBottleneck[t];
        int cur = t;
        while (cur != s) {
            int edge = prevEdgeIdx[cur];
            edgeList[edge].flow += pathBottleneck[t];
            edgeList[edge ^ 1].flow -= pathBottleneck[t];
            cur = edgeList[edge].src;
        }
        return true;
    }

    int computeMinCost(int s, int t) {
        int flow = 0, cost = 0;
        while (findPath(s, t, flow, cost));
        return cost;
    }
} graphSolver;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M >> K >> C >> D_val;
    for (int i = 1; i <= K; ++i) {
        scanf("%d", &A[i]);
    }

    sourceNode = 0;
    targetNode = N * 100 + 1;

    for (int i = 1; i <= K; ++i) {
        graphSolver.connect(sourceNode, 1 + (A[i] - 1) * 100, 1, 0);
    }

    for (int i = 1; i <= N; ++i) {
        int base = (i - 1) * 100LL;
        for (int j = 1; j < 100; ++j) {
            graphSolver.connect(base + j, base + j + 1, INT_MAX, C);
        }
    }

    for (int i = 1; i <= 100; ++i) {
        graphSolver.connect(i, targetNode, INT_MAX, 0);
    }

    while (M--) {
        int x, y;
        scanf("%d%d", &x, &y);
        for (int i = 1; i < 100; ++i) {
            int fromNode = (x - 1) * 100 + i;
            int toNode = (y - 1) * 100 + i + 1;
            for (int j = 1; j <= 50; ++j) {
                int cost = D_val * (j * j - (j - 1) * (j - 1)) + C;
                graphSolver.connect(fromNode, toNode, 1, cost);
            }
        }

        for (int i = 1; i < 100; ++i) {
            int fromNode = (y - 1) * 100 + i;
            int toNode = (x - 1) * 100 + i + 1;
            for (int j = 1; j <= 50; ++j) {
                int cost = D_val * (j * j - (j - 1) * (j - 1)) + C;
                graphSolver.connect(fromNode, toNode, 1, cost);
            }
        }
    }

    printf("%d\n", graphSolver.computeMinCost(sourceNode, targetNode));
    return 0;
}
